namespace Fanex.Age.UI.TotalBets
{
    using System;
    using System.Collections.Generic;
    using System.Data;
    using System.Web;
    using System.Web.UI;
    using Alpha.Web.Helpers;
    using Fanex.Age.UI;
    using Fanex.Age.UI.Components;
    using Fanex.Razorbill.Module.Core.Services.Impl;
    using Sunplus.Agent.Model.BL.Definitions;
    using Sunplus.Agent.Model.BL.TotalBets;
    using Sunplus.Agent.Utilities;
    using Fanex.Razorbill.Module.Core.Web;
    using Fanex.Razorbill.Module.Core.Utils;

    public partial class HomeDrawAwayNoBet_Page : TotalBets_Page
    {
        #region Variable
        private string rowBgOdd = Fanex.Age.UI.Common.RowBgOdd;
        private string rowBgEven = Fanex.Age.UI.Common.RowBgEven;
        private string rowBgLive = Fanex.Age.UI.Common.RowBgLive;
        private string rowBgClosed = Fanex.Age.UI.Common.RowBgClosed;
        #endregion

        #region Override

        public override void RenderContent(HtmlTextWriter writer)
        {
            var darkModeName = DarkModeHelper.GetDarkModeName(CurrentUserSession);
            if (!string.IsNullOrWhiteSpace(darkModeName))
            {
                rowBgOdd = DarkModeColor.RowBgOdd;
                rowBgEven = DarkModeColor.RowBgEven;
                rowBgLive = DarkModeColor.RowBgLive;
                rowBgClosed = DarkModeColor.RowBgClosed;
            }

            DataTable oddEventOneXTwo = View as DataTable;

            HomeDrawAwayNoBet_Template tpl = new HomeDrawAwayNoBet_Template();
            tpl.DarkModeName = darkModeName;

            tpl.Contents.LeagueContents.Clear();

            if (oddEventOneXTwo.Rows.Count > 0)
            {
                tpl.Contents.NotFoundContent.Hide();

                // Render league content
                int currentLeagueId = 0;
                int matchIndex = 0;
                HomeDrawAwayNoBet_Contents_LeagueContents_Block leagueBlock = new HomeDrawAwayNoBet_Contents_LeagueContents_Block();
                for (int i = 0; i < oddEventOneXTwo.Rows.Count; i++)
                {
                    DataRow dr = oddEventOneXTwo.Rows[i];

                    int leagueId = Convert.ToInt32(dr["leagueid"]);

                    if (i == 0 || currentLeagueId != leagueId)
                    {
                        // New league, ignore first row
                        if (i != 0) tpl.Contents.LeagueContents.Append(leagueBlock);

                        matchIndex = 1;
                        currentLeagueId = leagueId;

                        leagueBlock.MatchContents.Clear();
                        leagueBlock.LeagueName = CacheRef.GetLeagueName(leagueId);
                    }
                    else
                    {
                        matchIndex++;
                    }

                    HomeDrawAwayNoBet_Contents_LeagueContents_MatchContents_Block matchBlock = new HomeDrawAwayNoBet_Contents_LeagueContents_MatchContents_Block();
                    RenderMatchRow(matchBlock, dr, matchIndex, i + 1);

                    leagueBlock.MatchContents.Append(matchBlock);
                }

                if (leagueBlock != null) tpl.Contents.LeagueContents.Append(leagueBlock);
            }

            // Piwik
            if (Sunplus.Agent.Model.BL.Definitions.AppSettings.PiwikEnable)
            {
                tpl.Piwik.PiwikUrl = string.Format(
                    "{0}?idsite={1}",
                    Sunplus.Agent.Model.BL.Definitions.AppSettings.PiwikUrl,
                    Sunplus.Agent.Model.BL.Definitions.AppSettings.PiwikSiteId);
            }
            else
            {
                tpl.Piwik.Clear();
            }

            // Bet List Url
            tpl.BetListsUrl.BetListsUrl = MicroSites.BetListsUrl();

            if (_fullMode)
            {
                writer.Write(tpl);
            }
            else
            {
                writer.Write(tpl.Contents);
            }
        }

        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            if (!CurrentUserSession.SubPageAccess.ViewTotalBets)
            {
                return new ErrorPage_Page(Resources.Lang.strNotAccessPage);
            }

            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            return _TotalBetsBO.GetHomeDrawAwayNoBet();
        }
        #endregion

        #region Utility

        /// <summary>
        /// Render match row
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        /// <param name="matchIndex"></param>
        /// <param name="rowIndex"></param>
        private void RenderMatchRow(HomeDrawAwayNoBet_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr, int matchIndex, int rowIndex)
        {
            // Render match content
            // Row Color  and time value
            if (Convert.ToInt16(dr["liveindicator"]) == 1)
            {
                matchBlock.ColorClass = rowBgLive;
                matchBlock.TimeValue = dr["livehomescore"] + " - " + dr["liveawayscore"];
                matchBlock.LiveNotice.Show();
            }
            else
            {
                if (dr.Table.Columns.Contains("closed") && Convert.ToInt32(dr["closed"]) != 0)
                {
                    matchBlock.ColorClass = rowBgClosed;
                }
                else
                {
                    matchBlock.ColorClass = (matchIndex % 2) == 0 ? rowBgEven : rowBgOdd;
                }

                matchBlock.TimeValue = dr["showtime"].ToString();
                matchBlock.LiveNotice.Hide();
            }
            matchBlock.ColorOver = Fanex.Age.UI.Common.RowBgOver;

            // Event 
            matchBlock.Home = CacheRef.GetTeamName(Convert.ToInt32(dr["homeid"])) + (Convert.ToBoolean(dr["isNeutral"]) ? Resources.Lang.IsNeutral : string.Empty);
            matchBlock.Away = CacheRef.GetTeamName(Convert.ToInt32(dr["awayid"]));
            matchBlock.No = rowIndex.ToString();

            // Render value column
            RenderHNBTotal(matchBlock, dr);
            RenderDNBTotal(matchBlock, dr);
            RenderANBTotal(matchBlock, dr);
        }

        /// <summary>
        /// Render draw/no draw under total column
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        private void RenderHNBTotal(HomeDrawAwayNoBet_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr)
        {
            // Draw/no draw Total
            if (Convert.ToInt16(dr["betcount_HNB"]) != 0)
            {
                decimal HNBTotal = (decimal)(dr["home_odds_HNB"]) - (decimal)(dr["away_odds_HNB"]);
                matchBlock.HomeNoBetValue.HomeNoBetValue = Formater.DecFormat(HNBTotal, 0);
                matchBlock.HomeNoBetValue.MatchId = dr["matchid"].ToString();

                matchBlock.HomeNoBetValue.Show();
            }
            else
            {
                matchBlock.HomeNoBetValue.Hide();
            }
        }
        /// <summary>
        /// Render draw/no draw under total column
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        private void RenderDNBTotal(HomeDrawAwayNoBet_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr)
        {
            // Draw/no draw Total
            if (Convert.ToInt16(dr["betcount_DNB"]) != 0)
            {
                decimal DNBTotal = (decimal)(dr["home_odds_DNB"]) - (decimal)(dr["away_odds_DNB"]);
                matchBlock.DrawNoBetValue.DrawNoBetValue = Formater.DecFormat(DNBTotal, 0);
                matchBlock.DrawNoBetValue.MatchId = dr["matchid"].ToString();

                matchBlock.DrawNoBetValue.Show();
            }
            else
            {
                matchBlock.DrawNoBetValue.Hide();
            }
        }
        /// <summary>
        /// Render draw/no draw under total column
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        private void RenderANBTotal(HomeDrawAwayNoBet_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr)
        {
            // Draw/no draw Total
            if (Convert.ToInt16(dr["betcount_ANB"]) != 0)
            {
                decimal ANBTotal = (decimal)(dr["home_odds_ANB"]) - (decimal)(dr["away_odds_ANB"]);
                matchBlock.AwayNoBetValue.AwayNoBetValue = Formater.DecFormat(ANBTotal, 0);
                matchBlock.AwayNoBetValue.MatchId = dr["matchid"].ToString();

                matchBlock.AwayNoBetValue.Show();
            }
            else
            {
                matchBlock.AwayNoBetValue.Hide();
            }
        }
        /// <summary>
        /// Round color for negative number
        /// </summary>
        /// <param name="number"></param>
        /// <returns></returns>
        private static string NegativeNumberRoundColor(object number)
        {
            decimal num = Convert.ToDecimal(number);

            return (num < 0) ? "<font color='#eb6003'>" + Formater.DecFormat(num, 0) + "</font>" : Formater.DecFormat(num, 0);
        }
        #endregion
    }
}